import dotenv from 'dotenv';
import path from 'path';
import crypto from 'crypto';
dotenv.config();
// DECISION: Fallback to an autogenerated or dev encryption key if KEYGATE_MASTER_KEY is not supplied in dev mode, but ensure 32 bytes AES key derivation.
const rawKey = process.env.KEYGATE_MASTER_KEY || 'keygate_default_dev_master_key_secret_32bytes!';
const derivedMasterKey = crypto.createHash('sha256').update(rawKey).digest();
export const CONFIG = {
    port: parseInt(process.env.PORT || '3000', 10),
    host: process.env.HOST || '0.0.0.0',
    masterKey: derivedMasterKey,
    dbPath: process.env.KEYGATE_DB_PATH || path.resolve(process.cwd(), 'data', 'keygate.sqlite'),
    requireAuth: process.env.KEYGATE_REQUIRE_AUTH === 'false' ? false : true,
    logLevel: process.env.LOG_LEVEL || 'info',
    metricsRetentionDays: parseInt(process.env.METRICS_RETENTION_DAYS || '30', 10),
    circuitBreaker: {
        failureThreshold: parseInt(process.env.CB_FAILURE_THRESHOLD || '3', 10),
        successRateThreshold: parseFloat(process.env.CB_SUCCESS_RATE_THRESHOLD || '0.7'),
        baseCooldownMs: parseInt(process.env.CB_BASE_COOLDOWN_MS || '5000', 10),
        maxCooldownMs: parseInt(process.env.CB_MAX_COOLDOWN_MS || '300000', 10),
        quotaCooldownMs: parseInt(process.env.CB_QUOTA_COOLDOWN_MS || '86400000', 10), // 24 hours
    },
    defaultTimeoutMs: parseInt(process.env.DEFAULT_TIMEOUT_MS || '30000', 10),
};
